interface UploadedFile {
  id:            number
  user_id:       number | null
  original_name: string
  stored_name:   string
  mime_type:     string
  size_bytes:    number
  disk_path:     string
  is_image:      boolean
  url:           string | null
  created_at:    string
}

async function uploadFiles(
  uri:        string,
  setFiles:   (f: UploadedFile[]) => void,
  setLoading:(v: boolean) => void,
) {
  const f = await ImagePicker.getFileInfoAsync(uri)
  if (!f.size) throw new Error('Failed to get file info')
  try {
    const res = await arkzenFetch(`${BACKEND_URL}/api/upload-test/files`, {
      method: 'POST',
      headers: { 'Content-Type': 'multipart/form-data' },
      body: new FormData() as any,
    })
    const d = await res.json()
    if (!res.ok) throw new Error(d.message ?? 'Upload failed')
    const newFile: UploadedFile = {
      id:          d.data.id,
      user_id:     d.data.user_id,
      original_name: d.data.original_name,
      stored_name:   d.data.stored_name,
      mime_type:     d.data.mime_type,
      size_bytes:    d.data.size_bytes,
      disk_path:     d.data.disk_path,
      is_image:      !!d.data.is_image,
      url:           d.data.url,
      created_at:    d.data.created_at,
    }
    setFiles(prev => [...prev, newFile])
  } catch (e) {
    console.error('[upload-test] Upload failed:', e)
  } finally {
    setLoading(false)
  }
}

const FILE_THUMBNAILS = [
