]

export function FileThumbnail({ file }: { file: UploadedFile }) {
  const ext = file.original_name.split('.').pop()?.toLowerCase() ?? 'unknown'
  const thumb = FILE_THUMBNAILS.find(t => t.ext === ext) ?? { ext, color: '#9ca3af' }

  return (
    <View style={{ width: 48, height: 48, borderRadius: 12, backgroundColor: thumb.color }}>
      <Text style={{ fontSize: 13, fontWeight: '700', color: '#fff', textAlign: 'center', marginTop: 8 }}>
