  const [files, setFiles]     = useState<any[]>([])
  const [activeUpload, setActiveUpload] = useState<string | null>(null)
  const [deletePending, setDeletePending] = useState<number | null>(null)

  const showToast = (msg: string) => {
    console.log(`[upload-test] ${msg}`)
  }

  const loadFiles = useCallback(async () => {
    try {
      const res = await arkzenFetch(`${BACKEND_URL}/api/upload-test/files`)
      if (!res.ok) return
      const d = await res.json()
      setFiles(Array.isArray(d.data) ? d.data : Array.isArray(d) ? d : [])
    } catch {}
  }, [])

  useEffect(() => { loadFiles() }, [loadFiles])

  const doUpload = async (items: FileList | File[]) => {
    setActiveUpload?.(String(items.length))
    try {
      for (let i = 0; i < items.length; i++) {
        const f = items[i]
        const formData = new FormData()
        formData.append('file', f)
        formData.append('user_id', String(user?.id))
        await arkzenFetch(`${BACKEND_URL}/api/upload-test/files`, {
          method: 'POST',
          body: formData,
        })
      }
      await loadFiles()
    } finally {
      setActiveUpload(null)
    }
  }

  const handleDrop = (e: any) => {
    e.preventDefault()
    const dt = e.dataTransfer
    if (dt.files.length > 0) {
      doUpload(dt.files)
    }
  }

  const handleDragOver = (e: any) => {
    e.preventDefault()
  }

  const handleSingleChange = (ev: any) => {
    const files = ev.target.files as FileList
    if (files.length > 0) {
      doUpload(files)
    }
  }

  const handleDelete = async (id: number) => {
    setDeletePending(id)
    try {
      await arkzenFetch(`${BACKEND_URL}/api/upload-test/files/${id}`, { method: 'DELETE' })
      await loadFiles()
    } catch {} finally {
      setDeletePending(null)
    }
  }

  const handleLogout = async () => {
    await logout()
  }

  const formatSize = (b: number) => {
    const units = ['B', 'KiB', 'MiB', 'GiB', 'TiB']
    let i = 0
    while (b >= 1024 && i + 1 < units.length) {
      b /= 1024
      i++
    }
    return `${Math.round(b * 10) / 10} ${units[i]}`
  }

  return (
    <view className="flex-1 bg-neutral-50">

      {/* Header */}
      <view className="bg-white border-b border-neutral-100 px-5 py-4 flex-row items-center justify-between">
        <view>
          <text className="text-base font-semibold text-neutral-900">Uploaded Files</text>
          <text className="text-xs text-neutral-400 mt-0.5">{user?.name}</text>
        </view>
        <view bindtap={handleLogout}>
          <text className="text-xs text-neutral-400">Sign out</text>
        </view>
      </view>

      <scroll-view className="flex-1 p-4 gap-y-3">

        {/* Drop target */}
        <view
          onDrop={handleDrop}
          onDragOver={handleDragOver}
          style={{ minHeight: 160 }}
          className="border-2 border-dashed border-neutral-200 rounded-2xl flex-col items-center justify-center"
        >
          <text className="text-sm text-neutral-400 mb-1">Drop files here</text>
          <text className="text-xs text-neutral-300">or</text>
          <view bindtap={() => {}}>
            <text className="text-xs text-neutral-400 mt-1" style={{ cursor: 'pointer' }}>Select from device</text>
          </view>
          <input type="file" onChange={handleSingleChange} multiple accept="*" style={{ display: 'none' }} />
        </view>

        {/* Upload status */}
        {activeUpload !== null && (
          <view className="p-3 bg-blue-50 border border-blue-200 rounded-xl">
            <text className="text-xs text-blue-600 font-medium">Uploading {activeUpload} file{activeUpload !== '1' ? 's' : ''}…</text>
          </view>
        )}

        {/* Uploaded list */}
        {files.length === 0 ? (
          <view className="bg-white rounded-2xl border border-neutral-100 p-8 items-center">
            <text className="text-sm text-neutral-400">No files uploaded yet.</text>
            <text className="text-xs text-neutral-300 mt-1">Drop files above or tap Select from device to upload.</text>
          </view>
        ) : (
          files.map((f) => (
            <view key={f.id} className="bg-white rounded-2xl border border-neutral-100 p-3 flex-row items-start gap-2 pb-1.5">
              <view className={`w-9 h-9 rounded-lg items-center justify-center mr-3 ${
                f.is_image ? 'bg-neutral-100' : 'bg-neutral-100'
              }`}>
                {f.is_image
                  ? <text className="text-xs text-neutral-600">🖼</text>
                  : <text className="text-xs text-neutral-600">📄</text>
                }
              </view>
              <view className="flex-1 min-w-0">
                <text className="text-sm font-medium text-neutral-900 truncate" numberOfLines={1}>{f.original_name}</text>
                <text className="text-xs text-neutral-400 mt-0.5">{formatSize(f.size_bytes)}</text>
              </view>
              <view className="flex-row shrink-0 gap-x-2">
                {deletePending !== f.id ? (
                  <>
                    <view
                      bindtap={() => { showToast('Downloading…'); setTimeout(() => { window.open(f.disk_path, '_blank') }) }}
                      className="px-2 py-0.5 rounded-md items-center justify-center"
                    >
                      <text className="text-xs text-indigo-500">Download</text>
