  <pre className="bg-neutral-50 border border-neutral-100 rounded-lg p-4 text-sm overflow-x-auto">
    {result}
  </pre>
)

// ── Probe card ───────────────────────────────────────────────
const ProbeCard = ({
  probe,
  results,
  onRun,
}: {
  probe:   { key: string; desc: string; endpoint: string; method: string; type: string }
  results: ProbeResult[]
  onRun:   (probeKey: string) => void
}) => {
  const [result, setResult]        = useState<string | null>(null)
  const [loading, setLoading]      = useState(false)
  const [payload, setPayload]      = useState(probe.type === 'raw' ? '' : JSON.stringify({ message: 'Hello, Arkzen!' }, null, 2))
  const isEcho = probe.key === 'echo'

  const run = async () => {
    if (!result) return
    try {
      setLoading(true)
      setResult(null)
      const res = await arkzenFetch(`${BACKEND_URL}/api/body-endpoint-handler/probes/${probe.key}`, {
        method: 'POST',
        body:   isEcho ? payload : probe.type === 'raw' ? payload : JSON.stringify({ message: payload }),
      })
      const d = await res.json()
      setResult(JSON.stringify(d, null, 2))
      // Save result
      await arkzenFetch(`${BACKEND_URL}/api/body-endpoint-handler/probes/${probe.key}/results`, {
        method: 'POST',
        body:   JSON.stringify({
          probe:  probe.key,
          result: JSON.stringify(d),
          ok:     res.ok,
        }),
      })
    } catch (e) {
      setResult(e instanceof Error ? e.message : 'Request failed')
    } finally {
      setLoading(false)
    }
  }

  const ownResults = results.filter(r => r.probe === probe.key).slice(0, 3)

  return (
    <div className="card bg-white rounded-2xl border border-neutral-100 shadow-sm p-5">
      <div className="flex items-center justify-between mb-3">
        <div className={`badge badge-${probe.type === 'raw' ? 'blue' : 'purple'}`}>
          {probe.type === 'raw' ? 'raw body' : 'content-type'}
        </div>
        <code className="text-xs text-neutral-400">{probe.endpoint}</code>
      </div>

      {/* Payload input */}
      {(probe.type === 'json' || probe.type === 'form') && (
        <textarea
          value={payload}
          onChange={e => setPayload(e.target.value)}
          rows={3}
          placeholder="Payload — press Ctrl+Enter"
          onKeyDown={(e) => e.key === 'Enter' && e.shiftKey && run()}
          className="w-full resize-none bg-neutral-50 border border-transparent rounded-xl px-3 py-2 text-sm focus:border-neutral-300 focus:outline-none focus:ring-2 focus:ring-neutral-100 focus:ring-offset-2 transition-colors"
        />
      )}

      {isEcho && (
        <button
          onClick={() => navigator.clipboard.writeText(payload ?? '')}
          className="inline-flex items-center gap-1 text-xs text-neutral-400 hover:text-neutral-700 mt-2"
        >
          <Send size={13} /> Copy payload
        </button>
      )}

      {/* Run button */}
      <button
        onClick={run}
        disabled={loading}
        className="inline-flex items-center gap-1 w-full bg-neutral-900 text-white text-sm font-semibold py-2 rounded-xl hover:bg-neutral-700 transition-colors disabled:opacity-60"
      >
        {loading ? <RefreshCw className="animate-spin" size={14} /> : <Play size={14} />}
        Run
      </button>

      {/* Result */}
      {result && <ResultBox result={result} />}

      {/* Recent results */}
      {ownResults.length > 0 && (
        <div className="mt-3 space-y-1">
          {ownResults.map((r, i) => (
            <p key={i} className="text-xs text-neutral-400 truncate">{r.result}</p>
          ))}
        </div>
      )}
    </div>
  )
}

/* @arkzen:web:components:shared:end */

